-- Contenido original IO. Requiere esquema multimateria y migración 2026_10_05_materias_io.sql.
-- Aplicar SOLO a PostgreSQL local autorizada. No se ejecuta automáticamente.
-- Idempotencia por título de curso, (curso,orden) y configuracion_extra.semilla_clave.
BEGIN;
LOCK TABLE lms_core.cursos, lms_core.modulos, lms_core.ejercicios_practicos IN SHARE ROW EXCLUSIVE MODE;
SELECT setval(pg_get_serial_sequence('lms_core.cursos','id_curso'), GREATEST(COALESCE((SELECT MAX(id_curso) FROM lms_core.cursos),0), nextval(pg_get_serial_sequence('lms_core.cursos','id_curso'))), true);
SELECT setval(pg_get_serial_sequence('lms_core.modulos','id_modulo'), GREATEST(COALESCE((SELECT MAX(id_modulo) FROM lms_core.modulos),0), nextval(pg_get_serial_sequence('lms_core.modulos','id_modulo'))), true);
SELECT setval(pg_get_serial_sequence('lms_core.ejercicios_practicos','id_ejercicio'), GREATEST(COALESCE((SELECT MAX(id_ejercicio) FROM lms_core.ejercicios_practicos),0), nextval(pg_get_serial_sequence('lms_core.ejercicios_practicos','id_ejercicio'))), true);
INSERT INTO lms_core.cursos(titulo,materia_slug) VALUES ('IO I — Programación Lineal y Redes de Distribución','io') ON CONFLICT(titulo) DO NOTHING;
INSERT INTO lms_core.cursos(titulo,materia_slug) VALUES ('IO II — Modelos Estocásticos y Proyectos','io') ON CONFLICT(titulo) DO NOTHING;
DO $semilla$
DECLARE curso_id integer; modulo_id integer; ejercicio_id integer;
BEGIN
  SELECT id_curso INTO STRICT curso_id FROM lms_core.cursos WHERE titulo='IO I — Programación Lineal y Redes de Distribución' AND materia_slug='io';
  INSERT INTO lms_core.modulos(id_curso,titulo,orden,descripcion,xp_requerida,objetivos,errores_comunes)
  VALUES(curso_id,'Introducción a la Investigación de Operaciones',1,'La IO transforma una decisión en un modelo verificable. Primero delimita el problema, obtiene datos, formula variables y restricciones, resuelve, valida con la realidad y revisa los supuestos.',0,'["Distinguir decisiones, parámetros y restricciones","Conectar un modelo con una decisión real"]'::jsonb,'["Optimizar antes de definir la decisión","Confundir pronósticos con variables controlables"]'::jsonb)
