  RETURNING id_modulo INTO modulo_id;
  SELECT id_ejercicio INTO ejercicio_id FROM lms_core.ejercicios_practicos WHERE id_modulo=modulo_id AND configuracion_extra->>'semilla_clave'='io-unach-v1:io-i:1:1';
