    INSERT INTO lms_core.ejercicios_practicos(id_modulo,titulo,enunciado,query_maestra,dificultad,configuracion_extra,orden,tipo_mision,formato,visibilidad)
    VALUES(modulo_id,'Decidir qué producir','Una fábrica elige cantidades de mesas y sillas. ¿Qué elemento representan esas cantidades?','',2,'{"tipo_validacion":"NUMERICO","semilla_clave":"io-unach-v1:io-i:1:1","campos":[{"clave":"elemento","etiqueta":"Elemento","tipo":"opcion","opciones":["variable","parámetro","restricción"]}],"respuestas":{"elemento":"variable"},"tolerancia":{"abs":0.001,"rel":0.001},"curso_clave":"io-i","modulo_orden":1}'::jsonb,1,'HISTORIA','editor','GLOBAL');
  ELSE
