    VALUES(modulo_id,'Recurso limitado','La fábrica dispone de 40 horas de trabajo. ¿Qué parte del modelo representa ese límite?','',3,'{"tipo_validacion":"NUMERICO","semilla_clave":"io-unach-v1:io-i:1:2","campos":[{"clave":"elemento","etiqueta":"Elemento","tipo":"opcion","opciones":["objetivo","restricción","solución"]}],"respuestas":{"elemento":"restricción"},"tolerancia":{"abs":0.001,"rel":0.001},"curso_clave":"io-i","modulo_orden":1}'::jsonb,2,'HISTORIA','editor','GLOBAL');
  ELSE
