    VALUES(modulo_id,'Ganancia unitaria','Cada mesa x1 genera 3 y cada silla x2 genera 5. Escribe los coeficientes de max Z.','',2,'{"tipo_validacion":"NUMERICO","semilla_clave":"io-unach-v1:io-i:2:1","campos":[{"clave":"c1","etiqueta":"C1","tipo":"numero"},{"clave":"c2","etiqueta":"C2","tipo":"numero"}],"respuestas":{"c1":3,"c2":5},"tolerancia":{"abs":0.001,"rel":0.001},"curso_clave":"io-i","modulo_orden":2}'::jsonb,1,'HISTORIA','editor','GLOBAL');
